from solution import f
import math
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref(n):
    """Obviously-correct reference directly from spec."""
    out = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            out.append(math.factorial(i))
        else:
            out.append(i * (i + 1) // 2)
    return out


def test_example_f5():
    assert f(5) == [1, 2, 6, 24, 15]


def test_example_prefixes():
    assert f(1) == [1]
    assert f(2) == [1, 2]
    assert f(3) == [1, 2, 6]
    assert f(4) == [1, 2, 6, 24]


def test_zero_returns_empty():
    assert f(0) == []


def test_first_element_is_one():
    # i=1 is odd -> sum 1..1 == 1
    assert f(1)[0] == 1
    assert f(2)[0] == 1
    assert f(5)[0] == 1


def test_second_element_is_two():
    assert f(2)[1] == 2
    assert f(5)[1] == 2


@given(st.integers(min_value=0, max_value=20))
def test_size_equals_n(n):
    assert f(n) == ref(n)
    assert len(f(n)) == n


@given(st.integers(min_value=0, max_value=12))
def test_matches_reference_model(n):
    assert f(n) == ref(n)


@given(st.integers(min_value=1, max_value=15))
def test_even_positions_are_factorial(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 0:
            assert res[i - 1] == math.factorial(i)


@given(st.integers(min_value=1, max_value=15))
def test_odd_positions_are_triangular(n):
    res = f(n)
    for i in range(1, n + 1):
        if i % 2 == 1:
            assert res[i - 1] == i * (i + 1) // 2


@given(st.integers(min_value=1, max_value=12))
def test_all_elements_positive_ints(n):
    res = f(n)
    for v in res:
        assert isinstance(v, int)
        assert v >= 1


@given(st.integers(min_value=0, max_value=12))
def test_prefix_consistency(n):
    # f(n) prefix of f(n+1) when extended by one, per spec definition per-index
    a = f(n)
    b = f(n + 1)
    assert b[:n] == a
    assert b == ref(n + 1)
